	curr := d.tokens[d.cursor]

	// If the previous token is from a different file,
	// we can assume it's from a different line
	if prev.File != curr.File {
		return true
	}

	// If the previous token is from a different import chain
	// (e.g. a snippet imported in the same file), we can assume
	// it's from a different line, since line numbers of imported
	// tokens are relative to their original location
	if !slices.Equal(prev.imports, curr.imports) {
		return true
